mapper.select:
SELECT T1.LIST_ID, T2.CUSTOMER_NAME customerName, T1.CUSTOMER_ID, T2.INSITITUTE_CODE insitituteCode, T1.LIST_TYPE, T1.TERM, T1.AMOUNT, T1.EFF_DATE, T1.STATUS, T1.SEQ_ID, T1.UPDATE_TIME FROM REP_ACCESS_LIST T1 left join (select T.CUSTOMER_ID,INFO.CUSTOMER_NAME,T.INSITITUTE_CODE from MST_CUSTOMER_INFO_ADD t left join MST_CUSTOMER_INFO info on t.customer_id = info.customer_id where 1 = 1) T2 on T2.CUSTOMER_ID = T1.CUSTOMER_ID
where 1 = 1
and T1.STATUS = #{status, jdbcType=VARCHAR}
and T2.INSITITUTE_CODE LIKE CONCAT(CONCAT('%',#{insitituteCode, jdbcType=VARCHAR}),'%')
and T2.CUSTOMER_NAME LIKE CONCAT(CONCAT('%',#{customerName, jdbcType=VARCHAR}),'%')
and TO_CHAR(T1.UPDATE_TIME,'yyyy-MM-dd') >= #{startUpdateTime}
AND TO_CHAR(T1.UPDATE_TIME,'yyyy-MM-dd') <= #{endUpdateTime}
order by T1.UPDATE_TIME

select t.CUSTOMER_ID from MST_CUSTOMER_INFO_ADD t where substr(t.insititute_code,9,9) = #{insitituteCode,jdbcType=VARCHAR}

union 

select t.CUSTOMER_ID from MST_CUSTOMER_INFO_ADD t where t.insititute_code = substr(#{insitituteCode,jdbcType=VARCHAR},9,9)

union 

select t.CUSTOMER_ID from MST_CUSTOMER_INFO_ADD t where t.insititute_code = #{insitituteCode,jdbcType=VARCHAR}
